def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Iterate through the input string and identify each group of nested parentheses
    groups = []
    current_group = ""
    open_braces = 0

    for char in paren_string:
        if char == '(':
            open_braces += 1
        elif char == ')':
            open_braces -= 1

        current_group += char

        if open_braces == 0:
            groups.append(current_group)
            current_group = ""

    # Step 3: Check if each group is balanced by counting the number of open and close parentheses
    def is_balanced(group):
        stack = []
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

    # Filter out unbalanced groups
    groups = [group for group in groups if is_balanced(group)]

    # Step 4: Return the list of separated groups
    return groups
