def correct_bracketing(brackets: str):
    if set(brackets) != {'<', '>'}:
        return False

    count_open = brackets.count('<')
    count_close = brackets.count('>')

    if count_open != count_close:
        return False

    stack = []
    for bracket in brackets:
        if bracket == '<':
            stack.append(bracket)
        elif bracket == '>':
            if not stack:
                return False
            stack.pop()

    return len(stack) == 0
